INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_CONTINENTAL_GERMANIC','Continental (Romano-)Germanic',-100,400)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_SIMEK_NORTHERN','secondary scholarship','Rudolf Simek, Dictionary of Northern Mythology (trans. A. Hall, D. S. Brewer, 1993)','Reuse: standard reference for the Matronae and Continental Germanic deities.')
INSERT INTO _e VALUES
 ('ENT_CGE_PANTHEON','Continental Germanic Pantheon','collective','collective','Continental Germanic','pantheon','B','Hub collective for the Romano-Germanic deities of the Rhineland and Low Countries attested in votive inscriptions; modeling construct.'),
 ('ENT_CGE_MATRONAE','Matronae','collective','collective','Continental Germanic','motherhood, fertility, protection','B','The triple mother-goddesses of the Rhineland, attested on >1,000 votive stones (1st-4th c. CE), typically depicted as three seated women; named in numerous cult-epithet groups.'),
 ('ENT_CGE_MATRONAE_AUFANIAE','Matronae Aufaniae','deity','deity','Continental Germanic','motherhood, protection','B','Among the most-attested Matronae groups, centered on Bonn and Nettersheim; numerous inscriptions, esp. 2nd-3rd c. CE.'),
 ('ENT_CGE_MATRONAE_VACALLINEHAE','Matronae Vacallinehae','deity','deity','Continental Germanic','motherhood, protection','B','Matronae group worshipped chiefly at the large sanctuary of Pesch in the Eifel; ~150 inscriptions there.'),
 ('ENT_CGE_MATRONAE_GABIAE','Matronae Gabiae','deity','deity','Continental Germanic','motherhood, giving, abundance','B','Matronae group whose name relates to Germanic *geban ''to give''; cf. the Norse Gefjon/Gefn; attested in the Rhineland.'),
 ('ENT_CGE_MATRONAE_SULEVIAE','Matronae Suleviae / Suleviae','deity','deity','Continental Germanic','motherhood, household, protection','C','Mother/protective goddesses (Suleviae) attested across the Roman provinces incl. the Germanic Rhineland; ambiguously Celtic-Germanic, often grouped with the Matronae.'),
 ('ENT_CGE_NEHALENNIA','Nehalennia','deity','deity','Continental Germanic','seafaring, trade, protection, fertility','B','Goddess of seafarers and traders attested by ~160 votive altars at Domburg and Colijnsplaat (Zeeland), shown with dog, basket of fruit, and ship''s prow; 2nd-3rd c. CE.'),
 ('ENT_CGE_HERCULES_MAGUSANUS','Hercules Magusanus','deity','deity','Continental Germanic','strength, protection, war','B','Romano-Germanic god of the Batavians, an interpretatio Romana equating a native (Donar-like) hero with Hercules; widely attested in Lower Germany, 1st-3rd c. CE.'),
 ('ENT_CGE_BADUHENNA','Baduhenna','deity','deity','Continental Germanic','war, battle','C','Frisian goddess named by Tacitus (Annals IV.73) in connection with a sacred grove (lucus Baduhennae) where Roman soldiers were slain in 28 CE; name linked to *badwa ''battle''.'),
 ('ENT_CGE_TANFANA','Tanfana','deity','deity','Continental Germanic','fertility, cult-place','C','Goddess of the Marsi whose temple Germanicus destroyed (Tacitus, Annals I.51, 14 CE); a votive inscription also attests her; otherwise obscure.'),
 ('ENT_CGE_HLUDANA','Hludana','deity','deity','Continental Germanic','fertility, protection','C','Goddess attested by five inscriptions from the Lower Rhine/Frisian region; name often linked etymologically to Norse Hlodyn (an epithet of Jord, Thor''s mother).'),
 ('ENT_CGE_SANDRAUDIGA','Sandraudiga','deity','deity','Continental Germanic','fertility, abundance','C','Goddess known from a single votive altar at Zundert (North Brabant); name interpreted as ''she who gives wealth/red sand''; otherwise unknown.'),
 ('ENT_CGE_VAGDAVERCUSTIS','Vagdavercustis','deity','deity','Continental Germanic','war, virtue, protection','C','Germanic goddess attested on altars from the Lower Rhine (notably Cologne-Deutz, dedicated by a Praetorian prefect); name possibly meaning ''martial excellence''.'),
 ('ENT_CGE_REQUALIVAHANUS','Requalivahanus','deity','deity','Continental Germanic','protection (obscure)','C','Male Germanic god attested by votive inscriptions at Pesch in the Eifel; function unknown, name obscure.');
