INSERT INTO _r VALUES
 ('ENT_CGE_MATRONAE','member_of','ENT_CGE_PANTHEON','high','The Matronae collective belongs to the Continental Germanic religious sphere.'),
 ('ENT_CGE_NEHALENNIA','member_of','ENT_CGE_PANTHEON','high','Nehalennia is a Continental Germanic deity attested in the Low Countries.'),
 ('ENT_CGE_HERCULES_MAGUSANUS','member_of','ENT_CGE_PANTHEON','high','Hercules Magusanus is a Romano-Germanic Batavian deity.'),
 ('ENT_CGE_BADUHENNA','member_of','ENT_CGE_PANTHEON','high','Baduhenna is a Frisian (Continental Germanic) goddess.'),
 ('ENT_CGE_TANFANA','member_of','ENT_CGE_PANTHEON','high','Tanfana is a Continental Germanic goddess of the Marsi.'),
 ('ENT_CGE_HLUDANA','member_of','ENT_CGE_PANTHEON','high','Hludana is a Lower Rhine/Frisian Germanic goddess.'),
 ('ENT_CGE_SANDRAUDIGA','member_of','ENT_CGE_PANTHEON','high','Sandraudiga is a Continental Germanic goddess from Brabant.'),
 ('ENT_CGE_VAGDAVERCUSTIS','member_of','ENT_CGE_PANTHEON','high','Vagdavercustis is a Lower Rhine Germanic goddess.'),
 ('ENT_CGE_REQUALIVAHANUS','member_of','ENT_CGE_PANTHEON','high','Requalivahanus is a Continental Germanic god attested at Pesch.'),
 ('ENT_CGE_MATRONAE_AUFANIAE','member_of','ENT_CGE_MATRONAE','high','The Aufaniae are a named cult-group of the Matronae.'),
 ('ENT_CGE_MATRONAE_VACALLINEHAE','member_of','ENT_CGE_MATRONAE','high','The Vacallinehae are a named cult-group of the Matronae centered at Pesch.'),
 ('ENT_CGE_MATRONAE_GABIAE','member_of','ENT_CGE_MATRONAE','high','The Gabiae are a named cult-group of the Matronae.'),
 ('ENT_CGE_MATRONAE_SULEVIAE','member_of','ENT_CGE_MATRONAE','medium','The Suleviae are mother-goddesses frequently grouped with the Matronae in the Rhineland.'),
 ('ENT_CGE_REQUALIVAHANUS','associated_with','ENT_CGE_MATRONAE_VACALLINEHAE','medium','Requalivahanus and the Matronae Vacallinehae share the sanctuary cult-site of Pesch in the Eifel.'),
 ('ENT_CGE_MATRONAE','aligned_with','ENT_CEL_MATRES','high','The Germanic Matronae and the Celtic/Gaulish Matres/Matrones are the same triple-mother-goddess cult phenomenon across the Romano-provincial frontier (functional cognate).'),
 ('ENT_CGE_HERCULES_MAGUSANUS','equated_with','ENT_HERACLES','high','Hercules Magusanus is an interpretatio Romana that explicitly equates a native Germanic hero-god with the Greco-Roman Heracles/Hercules.'),
 ('ENT_CGE_HERCULES_MAGUSANUS','aligned_with','ENT_NOR_THOR','medium','Scholars connect the native god behind Hercules Magusanus with the thunder/strength god Donar, cognate of Norse Thor (Tacitus equated Germanic ''Hercules'' with the thunderer).'),
 ('ENT_CGE_HLUDANA','aligned_with','ENT_NOR_NERTHUS','low','Hludana is an earth/fertility goddess of the Germanic North Sea coast, broadly comparable to the earth-mother Nerthus; her name is also linked to the Norse earth-goddess epithet Hlodyn.'),
 ('ENT_CGE_MATRONAE_GABIAE','aligned_with','ENT_NOR_FRIGG','low','The Gabiae (''giving ones'') belong to the Germanic giving/fertility mother-goddess complex broadly aligned with Frigg and the Norse Gefjon (ENT_NOR_GEFJON).'),
 ('ENT_CGE_BADUHENNA','aligned_with','ENT_NOR_TYR','low','Baduhenna is a war/battle deity of the Frisii, sharing the Germanic martial-divinity sphere associated with Tiw/Tyr.'),
 ('ENT_CGE_NEHALENNIA','aligned_with','ENT_NOR_NERTHUS','low','Nehalennia is a coastal fertility/protective goddess of the Low Countries, broadly within the Germanic fertility-goddess sphere alongside Nerthus.');
